def _parse_pattern(pattern):
    length = len(pattern)
    pos = [0]

    def read_class_char(index):
        char = pattern[index]
        if char == "\\":
            if index + 1 >= length:
                raise ValueError("unterminated escape in class")
            return pattern[index + 1], index + 2
        return char, index + 1

    def parse_class():
        index = pos[0] + 1
        negate = False
        if index < length and pattern[index] == "^":
            negate = True
            index += 1
        ranges = []
        while True:
            if index >= length:
                raise ValueError("unterminated class")
            if pattern[index] == "]":
                break
            low, index = read_class_char(index)
            if index + 1 < length and pattern[index] == "-" and pattern[index + 1] != "]":
                high, index = read_class_char(index + 1)
                if low > high:
                    raise ValueError("bad range")
                ranges.append((low, high))
            else:
                ranges.append((low, low))
        if not ranges:
            raise ValueError("empty class")
        pos[0] = index + 1
        return ("cls", negate, ranges)

    def parse_atom():
        char = pattern[pos[0]]
        if char in "*+?":
            raise ValueError("nothing to repeat")
        if char == "(":
            pos[0] += 1
            inner = parse_alt()
            if pos[0] >= length or pattern[pos[0]] != ")":
                raise ValueError("unbalanced (")
            pos[0] += 1
            return ("cat", [inner])
        if char == "[":
            return parse_class()
        if char == ".":
            pos[0] += 1
            return ("any",)
        if char == "\\":
            if pos[0] + 1 >= length:
                raise ValueError("trailing backslash")
            escaped = pattern[pos[0] + 1]
            pos[0] += 2
            return ("lit", escaped)
        if char == "^":
            pos[0] += 1
            return ("bol",)
        if char == "$":
            pos[0] += 1
            return ("eol",)
        pos[0] += 1
        return ("lit", char)

    def parse_concat():
        items = []
        while pos[0] < length and pattern[pos[0]] not in "|)":
            atom = parse_atom()
            if pos[0] < length and pattern[pos[0]] in "*+?":
                if atom[0] in ("bol", "eol"):
                    raise ValueError("quantifier on assertion")
                quant = pattern[pos[0]]
                pos[0] += 1
                if quant == "*":
                    atom = ("star", atom)
                elif quant == "+":
                    atom = ("plus", atom)
                else:
                    atom = ("opt", atom)
                if pos[0] < length and pattern[pos[0]] in "*+?":
                    raise ValueError("stacked quantifier")
            items.append(atom)
        return ("cat", items)

    def parse_alt():
        branches = [parse_concat()]
        while pos[0] < length and pattern[pos[0]] == "|":
            pos[0] += 1
            branches.append(parse_concat())
        if len(branches) == 1:
            return branches[0]
        return ("alt", branches)

    tree = parse_alt()
    if pos[0] < length:
        raise ValueError("unbalanced )")
    return tree


def _build_nfa(tree):
    states = []

    def new_state(kind, data, target):
        states.append([kind, data, target])
        return len(states) - 1

    match_state = new_state("match", None, None)

    def build(node, next_state):
        kind = node[0]
        if kind == "cat":
            for child in reversed(node[1]):
                next_state = build(child, next_state)
            return next_state
        if kind == "alt":
            starts = [build(child, next_state) for child in node[1]]
            return new_state("split", None, starts)
        if kind in ("lit", "any", "cls"):
            return new_state("char", node, next_state)
        if kind in ("bol", "eol"):
            return new_state(kind, None, next_state)
        if kind == "opt":
            body = build(node[1], next_state)
            return new_state("split", None, [body, next_state])
        if kind == "star":
            loop = new_state("split", None, [])
            body = build(node[1], loop)
            states[loop][2] = [body, next_state]
            return loop
        if kind == "plus":
            loop = new_state("split", None, [])
            body = build(node[1], loop)
            states[loop][2] = [body, next_state]
            return body
        raise ValueError("unknown node")

    start_state = build(tree, match_state)
    return states, start_state


def _char_matches(node, char):
    kind = node[0]
    if kind == "any":
        return True
    if kind == "lit":
        return char == node[1]
    negate = node[1]
    found = False
    for low, high in node[2]:
        if low <= char <= high:
            found = True
            break
    return found != negate


def regex_search(pattern: str, text: str) -> bool:
    tree = _parse_pattern(pattern)
    states, start_state = _build_nfa(tree)
    text_length = len(text)
    cache = {}
    previous = frozenset()
    for index in range(text_length + 1):
        raw = previous | {start_state}
        at_start = index == 0
        at_end = index == text_length
        char = text[index] if index < text_length else None
        key = (raw, at_start, at_end, char)
        result = cache.get(key)
        if result is None:
            stack = list(raw)
            seen = set()
            matched = False
            char_states = []
            while stack:
                state_id = stack.pop()
                if state_id in seen:
                    continue
                seen.add(state_id)
                kind, data, target = states[state_id]
                if kind == "split":
                    stack.extend(target)
                elif kind == "bol":
                    if at_start:
                        stack.append(target)
                elif kind == "eol":
                    if at_end:
                        stack.append(target)
                elif kind == "match":
                    matched = True
                    break
                else:
                    char_states.append(state_id)
            if matched:
                result = (True, frozenset())
            elif char is None:
                result = (False, frozenset())
            else:
                following = set()
                for state_id in char_states:
                    node = states[state_id][1]
                    if _char_matches(node, char):
                        following.add(states[state_id][2])
                result = (False, frozenset(following))
            cache[key] = result
        matched, previous = result
        if matched:
            return True
    return False
